// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin;
    function setUp() public { 
        c = new C(); 
        admin = address(this);
    }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != admin);
        vm.assume(newOwner != address(0));

        address oldOwner = c.owner();

        // Call setOwner as non-admin
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, newOwner));

        // If call did not revert, the owner must be unchanged
        address finalOwner = c.owner();
        if (success) {
            assertTrue(finalOwner == oldOwner, "Non-admin changed owner");
        } else {
            assertTrue(finalOwner == oldOwner, "Reverting call still changed owner");
        }
    }
}

